<?php
$pageTitle=t('page_personnel_profile');$ws_id=(int)($_SESSION['workshop_id']??0);$uid=(int)($_GET['user_id']??$_POST['user_id']??0);$can_profile=is_strict_admin()||has_permission('manage_personnel')||access_mode('personnel')==='editor'||$uid===(int)($_SESSION['user_id']??0);if(!$uid||!$can_profile){showToast(t('دسترسی ندارید'),'error');redirect('index.php?page=personnel');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(($_POST['action']??'')==='upload_doc'){
  try{$path=operations_upload_file($_FILES['document']??[],'uploads/personnel_docs',['image/png'=>'png','image/jpeg'=>'jpg','application/pdf'=>'pdf'],12_000_000);if(!$path)throw new RuntimeException(t('فایل را انتخاب کنید.'));$expiry=to_gregorian($_POST['expiry_date']??'');$st=$pdo->prepare("INSERT INTO personnel_documents (user_id,workshop_id,title,document_type,file_path,expiry_date,notes,uploaded_by) VALUES (?,?,?,?,?,?,?,?)");$st->execute([$uid,$ws_id,sanitize($_POST['title']),sanitize($_POST['document_type']??''),$path,$expiry?:null,sanitize($_POST['notes']??''),$_SESSION['user_id']]);operations_audit($pdo,(int)$_SESSION['user_id'],'personnel_document','personnel_document',(int)$pdo->lastInsertId(),'مدرک '.($_POST['title']??''));showToast(t('مدرک ثبت شد.'));}catch(Throwable $e){showToast($e->getMessage(),'error');}redirect('index.php?page=personnel_profile&user_id='.$uid);
 }
 if(($_POST['action']??'')==='delete_doc'&&$can_profile){$pdo->prepare("DELETE FROM personnel_documents WHERE id=? AND user_id=?")->execute([(int)$_POST['doc_id'],$uid]);showToast(t('مدرک حذف شد.'));redirect('index.php?page=personnel_profile&user_id='.$uid);}
}
$user=null;$memberships=[];$docs=[];$inventory=[];$leaves=[];$hours=[];$salaryHistory=[];
try{$st=$pdo->prepare("SELECT u.* FROM users u WHERE u.id=?");$st->execute([$uid]);$user=$st->fetch();$st=$pdo->prepare("SELECT wp.*,w.name workshop_name FROM workshop_personnel wp JOIN workshops w ON w.id=wp.workshop_id WHERE wp.user_id=? ORDER BY wp.status='active' DESC,w.name");$st->execute([$uid]);$memberships=$st->fetchAll();$st=$pdo->prepare("SELECT * FROM personnel_documents WHERE user_id=? ORDER BY expiry_date IS NULL,expiry_date ASC,created_at DESC");$st->execute([$uid]);$docs=$st->fetchAll();$st=$pdo->prepare("SELECT t.*,i.name item_name,i.unit FROM inventory_transactions t JOIN inventory_items i ON i.id=t.item_id WHERE t.person_id=? AND t.deleted_at IS NULL AND t.return_date IS NULL ORDER BY t.checkout_date DESC");$st->execute([$uid]);$inventory=$st->fetchAll();$st=$pdo->prepare("SELECT * FROM leave_requests WHERE user_id=? ORDER BY start_date DESC LIMIT 20");$st->execute([$uid]);$leaves=$st->fetchAll();$st=$pdo->prepare("SELECT work_date,start_time,end_time,workshop_id FROM work_hours WHERE user_id=? ORDER BY work_date DESC,start_time DESC LIMIT 30");$st->execute([$uid]);$hours=$st->fetchAll();$st=$pdo->prepare("SELECT * FROM salary_history WHERE user_id=? ORDER BY start_date DESC,id DESC LIMIT 20");$st->execute([$uid]);$salaryHistory=$st->fetchAll();}catch(Throwable $e){}
if(!$user){echo t('پرسنل یافت نشد');exit;}include 'includes/header.php';
?>
<div class="d-flex justify-between align-center mb-4 animate-in"><h2>👤 <?= t('page_personnel_profile') ?> — <?=htmlspecialchars($user['full_name'])?></h2><a href="index.php?page=personnel" class="btn btn-ghost"><?= t('btn_back') ?></a></div>
<div class="stats-grid animate-in"><div class="stat-card"><div class="stat-icon primary"><i data-lucide="building-2"></i></div><div class="stat-info"><h3><?=count($memberships)?></h3><p><?= t('سابقه') ?> <?= t('nav_workshops') ?></p></div></div><div class="stat-card"><div class="stat-icon warning"><i data-lucide="package"></i></div><div class="stat-info"><h3><?=count($inventory)?></h3><p><?= t('کالای') ?> <?= t('نزد شخص') ?></p></div></div><div class="stat-card"><div class="stat-icon info"><i data-lucide="calendar-off"></i></div><div class="stat-info"><h3><?=count($leaves)?></h3><p><?= t('nav_leaves') ?> <?= t('ثبت') ?><?= t('‌شده') ?></p></div></div><div class="stat-card"><div class="stat-icon success"><i data-lucide="file-text"></i></div><div class="stat-info"><h3><?=count($docs)?></h3><p><?= t('مدرک') ?> <?= t('پیوست') ?></p></div></div></div>
<div class="grid-2 mt-4"><section class="card"><div class="card-header"><h3 class="card-title"><?= t('info') ?> <?= t('sal_base_pay') ?></h3></div><p><?= t('per_phone') ?>: <strong><?=htmlspecialchars($user['phone']?:'—')?></strong></p><p><?= t('per_national_code') ?>: <strong><?=htmlspecialchars($user['national_code']?:'—')?></strong></p><p><?= t('per_position') ?>: <strong><?=htmlspecialchars($user['position']?:$user['work_role']?:'—')?></strong></p><p><?= t('شبا:') ?> <strong dir="ltr"><?=htmlspecialchars($user['iban']?:'—')?></strong></p></section><section class="card"><div class="card-header"><h3 class="card-title"><?= t('سابقه') ?> <?= t('عضویت در') ?> <?= t('nav_workshops') ?></h3></div><?php foreach($memberships as $m):?><div style="padding:7px;border-bottom:1px solid var(--border)"><strong><?=htmlspecialchars($m['workshop_name'])?></strong> <span class="tag <?= $m['status']==='active'?'tag-active':'tag-rejected'?>"><?= $m['status']==='active' ? t('فعال') : t('غیرفعال') ?></span><div class="text-muted" style="font-size:11px"><?= t('wh_start') ?>: <?=$m['contract_start']?to_jalali($m['contract_start']):'—'?> · <?= t('پایان:') ?> <?=$m['ended_at']?to_jalali($m['ended_at']):'—'?></div></div><?php endforeach;?></section></div>
<div class="grid-2 mt-4"><section class="card"><div class="card-header"><h3 class="card-title">📦 <?= t('کالاهای نزد شخص') ?></h3><a class="btn btn-ghost btn-sm" href="index.php?page=inventory&tab=person&person_id=<?=$uid?>&person_name=<?=urlencode($user['full_name'])?>"><?= t('گزارش') ?> <?= t('nav_inventory') ?></a></div><?php foreach($inventory as $i):?><div style="padding:7px;border-bottom:1px solid var(--border)"><strong><?=htmlspecialchars($i['item_name'])?></strong> — <?=$i['quantity']?> <?=htmlspecialchars($i['unit'])?> · <?=to_jalali($i['checkout_date'])?></div><?php endforeach;?><?php if(empty($inventory)):?><p class="text-muted"><?= t('کالای') ?> <?= t('باقیمانده') ?> <?= t('نزد') ?> <?= t('این') ?> <?= t('شخص') ?> <?= t('نیست') ?>.</p><?php endif;?></section><section class="card"><div class="card-header"><h3 class="card-title">📅 <?= t('nav_leaves') ?>‌<?= t('های') ?> <?= t('اخیر') ?></h3></div><?php foreach($leaves as $l):?><div style="padding:7px;border-bottom:1px solid var(--border)"><?=to_jalali($l['start_date'])?> <?= t('تا') ?> <?=to_jalali($l['end_date'])?> <span class="tag <?= $l['status']==='approved'?'tag-active':'tag-pending'?>"><?= $l['status']==='approved' ? t('lea_approved') : ($l['status']==='pending' ? t('adv_pending') : t('btn_reject')) ?></span> <?=htmlspecialchars($l['reason']?:'')?></div><?php endforeach;?><?php if(empty($leaves)):?><p class="text-muted"><?= t('nav_leaves') ?> <?= t('ثبت نشده') ?> <?= t('است') ?>.</p><?php endif;?></section></div>
<div class="grid-2 mt-4"><section class="card"><div class="card-header"><h3 class="card-title">🗂 <?= t('مدارک') ?> <?= t('و') ?> <?= t('wh_date') ?> <?= t('انقضا') ?></h3><button class="btn btn-primary btn-sm" onclick="openModal('docModal')"><?= t('btn_add') ?> <?= t('مدرک') ?></button></div><?php foreach($docs as $d):$near=$d['expiry_date']&&strtotime($d['expiry_date'])<=strtotime('+30 day');?><div style="padding:8px;border-bottom:1px solid var(--border)"><a href="<?=htmlspecialchars($d['file_path'])?>" target="_blank"><strong><?=htmlspecialchars($d['title'])?></strong></a><?php if($d['expiry_date']):?><span class="tag <?=$near?'tag-rejected':'tag-active'?>"><?= t('انقضا') ?>: <?=to_jalali($d['expiry_date'])?></span><?php endif;?><?php if($can_profile):?><form method="post" style="display:inline"><?= get_csrf_field() ?><input type="hidden" name="action" value="delete_doc"><input type="hidden" name="doc_id" value="<?=$d['id']?>"><button class="btn btn-ghost btn-sm text-danger">🗑</button></form><?php endif;?></div><?php endforeach;?><?php if(empty($docs)):?><p class="text-muted"><?= t('مدرکی ثبت نشده است.') ?></p><?php endif;?></section><section class="card"><div class="card-header"><h3 class="card-title">🕓 <?= t('تغییرات') ?> <?= t('نرخ') ?> <?= t('nav_salary') ?></h3></div><?php foreach($salaryHistory as $h):?><div style="padding:7px;border-bottom:1px solid var(--border)"><?= $h['start_date']?to_jalali($h['start_date']):'اولیه'?>: <strong><?=number_format((float)$h['new_salary'])?></strong> · <?=htmlspecialchars($h['reason']?:'—')?></div><?php endforeach;?><?php if(empty($salaryHistory)):?><p class="text-muted"><?= t('رکوردی نیست.') ?></p><?php endif;?></section></div>
<div id="docModal" class="modal-overlay hidden"><div class="modal glass-modal"><div class="modal-header"><h3 class="modal-title"><?= t('btn_add') ?> <?= t('مدرک') ?></h3><button class="modal-close" onclick="closeModal('docModal')">✕</button></div><form method="post" enctype="multipart/form-data"><?= get_csrf_field() ?><input type="hidden" name="action" value="upload_doc"><input type="hidden" name="user_id" value="<?=$uid?>"><div class="modal-body"><div class="form-group"><label class="form-label"><?= t('عنوان') ?> *</label><input name="title" class="form-control" required></div><div class="form-row"><div class="form-group"><label class="form-label"><?= t('sal_type') ?> <?= t('مدرک') ?></label><input name="document_type" class="form-control" placeholder="<?= t('بیمه، HSE، گواهینامه...') ?>"></div><div class="form-group"><label class="form-label"><?= t('wh_date') ?> <?= t('انقضا') ?></label><input name="expiry_date" class="form-control jalali-date"></div></div><div class="form-group"><label class="form-label"><?= t('فایل') ?> *</label><input type="file" name="document" class="form-control" accept="image/png,image/jpeg,application/pdf" required></div><div class="form-group"><label class="form-label"><?= t('wh_note') ?></label><input name="notes" class="form-control"></div></div><div class="modal-footer"><button class="btn btn-primary"><?= t('ثبت') ?></button></div></form></div></div><?php include 'includes/footer.php'; ?>
